"""gwar.mil.ru, друга частина (08.11.2026): Петро Павлович Шутий і Опанас Петрович Оношко; доля «повернувся» для тих,
у кого в 1917–1922 рр. у Вороньках записані діти; розбіжності дат з раніше знайденими списками."""
import json
from PIL import Image
R = '/home/claude/rid-shutykh/'; MAN = R + 'seed/import/manifest.json'; IMP = R + 'seed/import/'; SRC = '/tmp/gwi/'
m = json.load(open(MAN)); have = {it.get('key') for it in m}
def put(rec, name):
    im = Image.open(SRC + 'gw_%s.jpg' % rec).convert('RGB'); im.save(IMP + name, quality=90)
    t = im.copy(); t.thumbnail((420, 420)); t.save(IMP + name.replace('.jpg', '-t.jpg'), quality=85)
G = 'https://gwar.mil.ru/heroes/'
ARCH = 'РДВІА (Російський державний військово-історичний архів), Картотека бюро обліку втрат у Першій світовій війні / Іменні списки втрат; «Память героев Великой войны 1914–1918» (gwar.mil.ru)'
new = []
def doc(did, recs, title, date, line, text, people):
    files, marks = [], []
    for i, (rec, t, mk) in enumerate(recs):
        fn = '%s_%d.jpg' % (did, rec); put(rec, fn); files.append({'file': fn, 'thumb': fn.replace('.jpg', '-t.jpg')}); marks.append({'p': i, **mk})
    if did in have: return
    extra = (' Інші записи: ' + ', '.join(G + t + str(r) + '/' for r, t, _ in recs[1:])) if len(recs) > 1 else ''
    new.append({'key': did, 'kind': 'doc', 'id': did, 'files': files, 'data': {'title': title, 'date': date, 'place': 'Чернігівська губ., Козелецький пов.',
        'src': ARCH + '. Записи: ' + ', '.join(str(r[0]) for r in recs) + '.', 'url': G + recs[0][1] + str(recs[0][0]) + '/', 'line': line, 'text': text + extra, 'people': people, 'marks': marks}})
doc('gw811petro', [(14185925, 'chelovek_donesenie', {'x': 0.02, 'y': 0.33, 'w': 0.96, 'h': 0.04}), (14782256, 'chelovek_donesenie', {'x': 0.02, 'y': 0.71, 'w': 0.96, 'h': 0.045})],
    'Перша світова: Петро Павлович Шутий, 11-й Фінляндський стрілецький полк, 1916 р.', '04.09.1916',
    'Іменний список втрат, рядок 757: «Шутый Петръ Павловъ», «Черниговской», «Козелецкаго», «Вороньковской вол. и села»; «Пропал без вести», 1916, 4 вересня. Інший список: «Шутый Петръ Павловъ», «Черниговской», «Козелецкаго», «Вороньковской и села»; «ранен» 5 січня, відправлений у дивізійний лазарет (у базі — 05.01.1916; 11-й Фінляндський стрілецький полк).',
    'Є припущення, що це [[p:s20_petro_p|Петро Павлович Шутий]] (нар. 25.06.1895) — на підставі імені, по батькові й села.', ['s20_petro_p'])
doc('gw811onoshko', [(24242118, 'chelovek_gospital', {'x': 0.01, 'y': 0.01, 'w': 0.98, 'h': 0.98})],
    'Перша світова: Опанас Петрович Оношко, 4-й Фінляндський стрілецький полк, 1916 р.', '02.12.1916',
    'Картка «на прибувших»: «Оношко Аѳонасій Петровичъ», «р. 4-го Финляндскаго», «Черниговской», «Козелецкаго», «Вороньковской», селение «то-же»; «Боленъ»; 1-й Київський госпіталь Південно-Західного обласного земського комітету, Дорогожицька, 68; поступив 2.12.[1916].',
    'Є припущення, що це [[p:a7_083|Опанас Петрович Оношко]] (бл. 1892), який 1911 р. повінчався з Марією Вдовинець, — на підставі імені, по батькові, рідкісного прізвища й волості.', ['a7_083'])
PP = [
 ('gw811b-petro', 's20_petro_p', {'war': {'w': 'ww1', 'f': 'mis', 'h': True}},
  'Перша світова: «Шутый Петр Павлович» з Вороньківської волості, 11-й Фінляндський стрілецький полк, — поранений 5.01.1916, а 4.09.1916 записаний пропалим безвісти ([[d:gw811petro|списки]]). Є припущення, що це він — на підставі імені, по батькові й села.', None),
 ('gw811b-onoshko', 'a7_083', {'n': 'Афанасій', 'war': {'w': 'ww1', 'f': 'unk', 'h': True}},
  'У картотеці втрат Першої світової — «Оношко Аѳонасій Петровичъ» з Вороньківської волості, рядовий 4-го Фінляндського стрілецького полку, хворий, 2.12.1916 поступив у київський госпіталь ([[d:gw811onoshko|картка]]); там ім\'я написане чітко — «Аѳонасій». Є припущення, що це він — на підставі імені, по батькові, рідкісного прізвища й волості.', None),
 ('gw811b-andrii', 'andrii_f', {'war': {'w': 'ww1', 'f': 'ret', 'h': True}},
  'Після війни — у Вороньках: 3.12.1920 у «Андрея Феод.» і «Улианы Михай…» Шутих народилася дочка [[p:olha_af20|Ольга]] ([[d:scz1920an|запис ЗАГС]]), тож якщо поранений 1915 р. ефрейтор — це він, то він повернувся.', None),
 ('gw811b-leontii', 'r6_leontii_k', {'war': {'w': 'ww1', 'f': 'ret', 'h': True}},
  'Пропалим безвісти його записали помилково: у липні 1916 р. він уже в лазареті. Після поранення — у Вороньках: «Леонтій Корниліевъ Шутый» записаний батьком дітей 11.06.1917 ([[d:r8d01|метрика]]) і 5.02.1919 ([[d:r8d03|метрика]]), «Шутой Леонтий Корнеев» — 25.08.1921 ([[d:r23d01|запис ЗАГС]]).', None),
 ('gw811b-yakiv', 'yakiv_an', {'war': {'w': 'ww1', 'f': 'ret', 'h': True}},
  'Після війни — у Вороньках: «Іаковъ Антоніевъ Шутый» записаний батьком 14.02.1919 ([[d:scyk1919|метрика]]) і 19.08.1922 ([[d:scyk1922|запис ЗАГС]]).', None),
 ('gw811b-kyrylo', 'r24_kyrylo', {'war': {'w': 'ww1', 'f': 'ret', 'h': True}},
  'Після поранення — у Вороньках: «Кирилл Артемов Вдовинец» записаний батьком 22.12.1917 ([[d:r24d12|метрика]]) і 15.09.1922 ([[d:r26d01|запис ЗАГС]]).', None),
 ('gw811b-polievkt', 'polievkt', None,
  'Розбіжність: у зведеному списку втрат Чернігівської губернії ([[d:ww1sh|скріншот]]) дата поранення — 20.08.1914, а в іменному списку 277-го полку і в базі gwar — 20 грудня 1914 р.; можливо, це два різні поранення.', None),
 ('gw811b-ioann', 'r6_ioann_o2', None,
  'У зведеному списку втрат Чернігівської губернії є ще «Рядов. Шутый Ив. Алекс.» з Вороньківської волості, поранений 18.08.1914 ([[d:ww1sh|скріншот]]); чи це той самий Іван — невідомо.', None),
 ('gw811b-illia', 'illia_im', None,
  'Зауваження: батьком [[p:ivan_il21|Івана]] (10.01.1921) у записі ЗАГС названо «Шутой Илья Иванов», 1889 р. н. Якщо це наш Ілля (нар. 1894), то пропалий безвісти 1915 р. повернувся (зниклих безвісти часто брали в полон); а можливо, в селі було два Іллі Івановичі.', None),
]
for key, pid, st, app, _ in PP:
    if key in have: continue
    x = {'key': key, 'kind': 'personpatch', 'person': pid, 'append': app}
    if st: x['set'] = st
    new.append(x)
m.extend(new); json.dump(m, open(MAN, 'w'), ensure_ascii=False, indent=1); print('додано', len(new))
# Історія роду
m = json.load(open(MAN)); have = {it.get('key') for it in m}
if 'gw811b-text-history' not in have:
    H = [x for x in m if x['kind'] == 'text' and x.get('id') == 'history'][-1]; md = H['value']['md']
    A = '- [[p:trokhym_per|Трохим Степанович Перчета]] з Озерян — 333-й Глазовський полк, поранений у ліву руку 17.11.1916 у Карпатах ([[d:gw811trokhym|список і картка]]).\n'
    B = A + ('- [[p:s20_petro_p|Петро Павлович Шутий]] — 11-й Фінляндський стрілецький полк, поранений 5.01.1916, пропав безвісти 4.09.1916 ([[d:gw811petro|списки]]).\n'
             '- [[p:a7_083|Опанас Петрович Оношко]] — 4-й Фінляндський стрілецький полк, хворий, грудень 1916 р., київський госпіталь ([[d:gw811onoshko|картка]]).\n\n'
             'Четверо з них, якщо ототожнення правильне, повернулися: у 1917–1922 рр. у Вороньках записані діти Леонтія Корнійовича, Якова Антоновича, Кирила Вдовинця й Андрія Федоровича. '
             'Леонтія 23.05.1916 записали пропалим безвісти, але в липні 1916 р. він уже лежав у лазареті.\n')
    md2 = md.replace(A, B, 1).replace('Петро Павлович (пропав безвісти 4.09.1916), ', '', 1)
    assert md2 != md
    v = dict(H['value']); v['md'] = md2
    m.append({'key': 'gw811b-text-history', 'kind': 'text', 'id': 'history', 'value': v})
    json.dump(m, open(MAN, 'w'), ensure_ascii=False, indent=1); print('історію оновлено')
